"""Stack samples of game processes running the C++ search: where a game thread's engine time goes."""
import json, sys
from collections import Counter
from pathlib import Path

sys.path.insert(0, "SCRATCH/engine_profile")
from samples import CALLS, CHECKS, ENGINE, entry, game_threads, kind_of_work, thread_state  # noqa: E402

# Parts of the C++ search, by the outermost frame below the search that matches one.
PARTS = (
    ("playing an action", ("Engine::step(",)),
    ("playing a declaration", ("Engine::interrupt(",)),
    ("rolling dice", ("Engine::resolveChance(",)),
    ("listing legal actions", ("Engine::actionMenu(", "Engine::legalActionMenu(")),
    ("listing declarations", ("Engine::interruptMenu(", "Engine::legalInterruptMenu(")),
    ("encoding the state", ("encodeZoneInput(",)),
    ("copying the game", ("Engine::cloneForSearch", "Engine::clone(")),
    ("destroying copies", ("Engine::~Engine", "State::~State", "__shared_ptr_emplace<game::campaign::Engine",
                           "deque<game::campaign::(anonymous namespace)::Node")),
    ("the state key", ("Engine::stateKey(", "State::planningKey(")),
    ("sending requests and reading replies", ("InferenceClient::evaluate",)),
    ("the zone encoding version", ("zoneEncodingSpec(",)),
)


def search_part(frames):
    names = [function for function, library in frames if library == ENGINE]
    inside = False
    for name in names:
        if "searchDecision" in name:
            inside = True
            continue
        if not inside:
            continue
        for part, keys in PARTS:
            if any(key in name for key in keys):
                return part
    return "the search's own work" if inside else None


def report(paths):
    states, parts, checks, kinds, calls = Counter(), Counter(), Counter(), Counter(), Counter()
    for path, thread, frames, count in game_threads(paths):
        state = thread_state(frames)
        states[state] += count
        if state != "engine":
            continue
        part = search_part(frames)
        if part is None:
            first = entry(frames)
            part = "from Python: " + next((name for name, keys in CALLS if any(key in first for key in keys)), "other calls")
        parts[part] += count
        names = [function for function, library in frames if library == ENGINE]
        for check, keys in CHECKS:
            if any(any(key in name for key in keys) for name in names):
                checks[check] += count
        kinds[kind_of_work(*frames[-1])] += count
    engine, total = states["engine"], sum(states.values())

    def shares(counter, whole):
        return {name: round(count / whole, 4) for name, count in counter.most_common()}

    return {"game_thread_samples": total, "engine_samples": engine, "thread_states": shares(states, total),
            "engine_parts": shares(parts, engine), "checks_inclusive_overlapping": shares(checks, engine),
            "kind_of_innermost_work": shares(kinds, engine)}


if __name__ == "__main__":
    print(json.dumps(report(sys.argv[1:]), indent=1))

