"""Read macOS /usr/bin/sample reports of game processes: where game threads spend their samples.

parse(path) yields (thread, frames, samples) for every leaf of the call graph, frames from the
thread's root to the innermost function, each frame (function, library).
"""
from __future__ import annotations

import re
import sys
from collections import Counter

LINE = re.compile(r"^(?P<prefix>[ +!:|]*)(?P<count>\d+) (?P<frame>.*)$")
FRAME = re.compile(r"^(?P<function>.*?)\s+\(in (?P<library>[^)]+)\)(?:\s+\+ [0-9,.]+)?(?:\s+\[[0-9a-fx,.]+\])?\s*$")
ENGINE = "gwrl_cpp.cpython-313-darwin.so"


def frame_of(text: str) -> tuple[str, str]:
    match = FRAME.match(text.strip())
    if match:
        return match.group("function"), match.group("library")
    return text.strip().split("  [")[0], "?"


def parse(path):
    text = open(path, errors="replace").read()
    graph = text.split("Call graph:", 1)[1].split("Total number in stack", 1)[0]
    stack = []  # [depth, frame, count, children total]
    thread = None

    def close(to_depth):
        nonlocal stack
        while stack and stack[-1][0] >= to_depth:
            depth, frame, count, children = stack.pop()
            if stack:
                stack[-1][3] += count
            own = count - children
            if own > 0:
                yield thread, [entry[1] for entry in stack] + [frame], own

    for line in graph.splitlines():
        match = LINE.match(line)
        if not match:
            continue
        depth = len(match.group("prefix")) // 2
        if depth <= 2:  # A thread's line.
            yield from close(0)
            thread = match.group("frame").strip()
            stack = []
            continue
        yield from close(depth)
        stack.append([depth, frame_of(match.group("frame")), int(match.group("count")), 0])
    yield from close(0)


WAITS = ("__psynch_cvwait", "__psynch_mutexwait", "read", "__read_nocancel", "__semwait_signal", "__select",
         "kevent", "kevent64", "mach_msg2_trap", "__workq_kernreturn", "__ulock_wait", "__ulock_wait2", "poll",
         "__recvfrom", "recvfrom", "__wait4", "__sigsuspend", "semaphore_wait_trap", "__recvmsg", "__sendmsg")


def main(paths):
    leaves = Counter()
    total = 0
    for path in paths:
        for thread, frames, count in parse(path):
            total += count
            leaves[frames[-1][0]] += count
    print(total)
    for name, count in leaves.most_common(25):
        print(count, name[:150])


if __name__ == "__main__":
    main(sys.argv[1:])


def in_engine(frames) -> bool:
    return any(library == ENGINE for _, library in frames)


def thread_state(frames) -> str:
    """What a game thread's sample was doing."""
    leaf = frames[-1][0]
    names = [function for function, _ in frames]
    gil = any(name in ("take_gil", "PyEval_RestoreThread", "PyEval_AcquireThread", "_PyEval_ReInitThreads")
              for name in names)
    if leaf in WAITS or leaf.startswith("__psynch") or leaf.startswith("__ulock"):
        if gil:
            return "wait: interpreter lock after an engine call" if in_engine(frames) else "wait: interpreter lock"
        if leaf in ("read", "__read_nocancel", "__recvfrom", "recvfrom", "__recvmsg"):
            return "wait: pipe read (inference server)"
        return "wait: other"
    if gil:
        return "wait: interpreter lock (spinning)"
    if in_engine(frames):
        return "engine"
    return "python and other libraries"


def game_threads(paths):
    """Every sample of threads that ever called the engine, by thread."""
    for path in paths:
        by_thread = {}
        for thread, frames, count in parse(path):
            by_thread.setdefault(thread, []).append((frames, count))
        for thread, rows in by_thread.items():
            if any(in_engine(frames) for frames, _ in rows):
                for frames, count in rows:
                    yield path, thread, frames, count


def entry(frames) -> str:
    """The first engine function below pybind11's dispatcher: the call Python made."""
    seen_dispatch = False
    for function, library in frames:
        if library != ENGINE:
            continue
        if "dispatcher" in function or function.startswith("pybind11::"):
            seen_dispatch = True
            continue
        if seen_dispatch and not function.startswith("pybind11::") and "NativeCampaignEnv::call" not in function:
            return function
    return "?"


def discover(paths):
    states, entries, inclusive = Counter(), Counter(), Counter()
    engine = 0
    for path, thread, frames, count in game_threads(paths):
        state = thread_state(frames)
        states[state] += count
        if state == "engine":
            engine += count
            entries[entry(frames)[:140]] += count
            for name in {function for function, library in frames if library == ENGINE}:
                inclusive[name[:140]] += count
    total = sum(states.values())
    print("game-thread samples", total)
    for name, count in states.most_common():
        print(f"  {count / total:6.1%} {name}")
    print("engine samples", engine)
    for name, count in entries.most_common(30):
        print(f"  {count / engine:6.1%} {name}")
    print("inclusive")
    for name, count in inclusive.most_common(120):
        print(f"  {count / engine:6.1%} {name}")


