def kind_of_work(function: str, library: str) -> str:
    if "memcmp" in function:
        return "comparing strings"
    if function.startswith(("operator new", "operator delete", "malloc", "free", "_free", "_malloc", "nanov2", "_nanov2",
                            "szone", "_szone", "xzm", "_xzm", "mfm_", "tiny_", "small_", "_realloc", "realloc",
                            "default_zone", "_platform_bzero$VARIANT")) or "malloc" in function:
        return "allocating and freeing memory"
    if "__init_copy_ctor_external" in function or "basic_string" in function:
        return "copying and building strings"
    if "_platform_memmove" in function or "_platform_memset" in function or function.startswith(("memcpy", "bzero", "memset")):
        return "copying and filling memory"
    if "__tree" in function or "__hash_table" in function or "NameTable" in function or "murmur2" in function \
            or "lowerBound" in function or "SlotMap" in function and "lookup" in function:
        return "looking up maps and hash tables"
    if "game::json::" in function or "__variant_detail" in function:
        return "reading and copying JSON values"
    if library == ENGINE:
        return "the rules' own code"
    if library.startswith("python") or library.startswith("libpython"):
        return "Python's interpreter"
    return "other libraries"


def report(paths):
    """Shares for the record: thread states, engine calls, checks and kinds of work."""
    states, calls, checks, kinds, inclusive = Counter(), Counter(), Counter(), Counter(), Counter()
    per_file = {}
    for path, thread, frames, count in game_threads(paths):
        state = thread_state(frames)
        states[state] += count
        per_file.setdefault(path, Counter())[state] += count
        if state != "engine":
            continue
        first = entry(frames)
        calls[next((name for name, keys in CALLS if any(key in first for key in keys)), "other calls")] += count
        names = [function for function, library in frames if library == ENGINE]
        for check, keys in CHECKS:
            if any(any(key in name for key in keys) for name in names):
                checks[check] += count
        for name in set(names):
            inclusive[name] += count
        kinds[kind_of_work(*frames[-1])] += count
    engine = states["engine"]
    total = sum(states.values())

    def shares(counter, whole):
        return {name: round(count / whole, 4) for name, count in counter.most_common()}

    return {"game_thread_samples": total, "engine_samples": engine,
            "thread_states": shares(states, total),
            "thread_states_by_sample": {Path(path).name: shares(counter, sum(counter.values()))
                                        for path, counter in per_file.items()},
            "engine_calls": shares(calls, engine), "checks_inclusive_overlapping": shares(checks, engine),
            "kind_of_innermost_work": shares(kinds, engine),
            "top_inclusive_functions": {name[:160]: round(count / engine, 4) for name, count in inclusive.most_common(60)}}


from pathlib import Path  # noqa: E402


def callers_of(paths, kinds, depth=1):
    """For engine samples whose innermost work is one of `kinds`, the nearest named engine callers."""
    result = Counter()
    skip = ("std::", "game::json::", "decltype", "void std::", "bool std::", "operator new", "operator delete")
    for path, thread, frames, count in game_threads(paths):
        if thread_state(frames) != "engine" or kind_of_work(*frames[-1]) not in kinds:
            continue
        named = [function for function, library in frames if library == ENGINE and not function.startswith(skip)
                 and "basic_string" not in function]
        result[" <- ".join(name[:90] for name in reversed(named[-depth:])) if named else "?"] += count
    return result


def inside_call(paths, call_name, top=40):
    """Within one engine call (a CALLS name), each engine function's inclusive share of its samples."""
    keys = dict(CALLS)[call_name]
    inclusive, total = Counter(), 0
    for path, thread, frames, count in game_threads(paths):
        if thread_state(frames) != "engine":
            continue
        if not any(key in entry(frames) for key in keys):
            continue
        total += count
        for name in {function for function, library in frames if library == ENGINE}:
            inclusive[name] += count
    return total, [(round(count / total, 4), name[:150]) for name, count in inclusive.most_common(top)]
